// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address originalOwner, address caller, address newOwner) public {
        // Restrict: originalOwner must be address(0) because no owner is set initially
        vm.assume(originalOwner == address(0));
        // Set initial owner
        vm.prank(originalOwner);
        c.transferOwnership(originalOwner);

        // Act: call transferOwnership as the current owner
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);

        // Observe: ownership should have been transferred to newOwner
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        address oldOwner = c.owner();
        c.transferOwnership(newOwner);
        c.owned();
        // General rule: after owned() on a contract with transferred ownership, the owner should be the new owner
        assertTrue(c.owner() == newOwner);
    }
}
